const topics={
  overview:{label:'Overview',eyebrow:'THE PROTOCOL DESIGN',title:'One market. Connected uses.',intro:'Rillvane brings RLVN/USDC trading, single-asset supply, and collateral-backed USDC credit into one market.',body:`<div class="protocol-reader-flow"><span>Supply one asset</span><i>→</i><span>Market liquidity</span><i>→</i><span>Trade / Credit</span></div><h3>The core idea</h3><p>The market is an oracle-priced inventory pool, not a CLOB. Deposit a single eligible asset, inspect cash and utilization, trade exact-in, or manage a credit position from the same workspace.</p><h3>What changes for the user</h3><ul><li><strong>Suppliers</strong> hold NAV shares in RLVN or USDC, with withdrawals bound by spendable cash.</li><li><strong>Traders</strong> see oracle price, fee, impact, and minimum received on a market exact-in ticket.</li><li><strong>Borrowers</strong> post RLVN collateral, borrow USDC at 50% LTV, and track health against a 60% liquidation threshold.</li></ul>`},
  pool:{label:'Pools',eyebrow:'SINGLE-ASSET LIQUIDITY',title:'Deposit one asset. Read the whole position.',intro:'A supplier starts with one eligible asset rather than a matched two-token LP deposit.',body:`<h3>Three balances to distinguish</h3><dl class="protocol-definitions"><div><dt>Supplied position</dt><dd>NAV shares in RLVN or USDC. Quote NAV equals cash plus loans receivable.</dd></div><div><dt>Utilized liquidity</dt><dd>Outstanding USDC loans versus quote NAV. Utilization sets the supplier APY against the 8% borrow APR.</dd></div><div><dt>Available cash</dt><dd>Spendable vault cash. Loans are not cash: the same units cannot back a swap, a loan, and a withdrawal.</dd></div></dl><h3>Reserve floor</h3><p>10% of quote NAV remains unborrowable so the pool can still settle swaps and withdrawals.</p>`},
  execution:{label:'Execution',eyebrow:'FROM QUOTE TO OUTCOME',title:'Inspect the trade before you place it.',intro:'A quote binds oracle price, fee, impact, and minimum received. You sign the instruction; the program re-checks every constraint.',body:`<ol class="protocol-steps"><li><strong>Select the side.</strong><p>Buy or sell RLVN against USDC from the trading terminal.</p></li><li><strong>Request a quote.</strong><p>Quotes expire in 15 seconds. Output is floored; the ticket is market exact-in only.</p></li><li><strong>Sign the instruction.</strong><p>Your wallet signs the prepared message. The backend verifies the signature, then applies the instruction.</p></li></ol><h3>What the quote means</h3><dl class="protocol-definitions"><div><dt>Oracle price</dt><dd>Starting value 100 USDC per RLVN. Stale quotes (30s) are rejected.</dd></div><div><dt>Price impact</dt><dd>min(190 bps, size / cash × 10,000). Execution more than 5% from oracle is rejected.</dd></div><div><dt>Fee</dt><dd>10 bps to USDC suppliers.</dd></div></dl>`},
  supply:{label:'Supply',eyebrow:'SUPPLIER POSITIONS',title:'Read the rate alongside the liquidity.',intro:'Supply is an asset-denominated NAV claim. Total shares and spendable cash are different numbers.',body:`<h3>How the position works</h3><p>The first deposit mints shares 1:1. Later deposits mint amount × total shares / NAV. Redeeming burns shares for assets from cash, never from receivables.</p><h3>Returns</h3><p>USDC suppliers earn the 8% borrow APR pro-rata to utilization, plus swap fees. RLVN inventory earns no borrow interest.</p><h3>A withdrawal is a cash event</h3><p>Your share balance can exceed immediately available cash. The 10% reserve floor can also block a redemption.</p><a class="protocol-reader-link" href="/app/#earn">Open supply markets <span>↗</span></a>`},
  credit:{label:'Credit',eyebrow:'COLLATERAL-BACKED USDC',title:'Borrow against a visible buffer.',intro:'Post RLVN, borrow USDC. Interest accrues on-chain at a fixed 8% APR.',body:`<h3>The position model</h3><dl class="protocol-definitions"><div><dt>Collateral value</dt><dd>RLVN quantity × oracle price.</dd></div><div><dt>Loan-to-value</dt><dd>Outstanding debt ÷ collateral value. Max LTV is 50%.</dd></div><div><dt>Liquidation</dt><dd>At 60% LTV the keeper can repay 50% of debt and seize collateral with a 5% bonus.</dd></div></dl><h3>Parameters</h3><div class="protocol-example"><div><span>Collateral</span><strong>RLVN</strong></div><div><span>Borrowing limit</span><strong>50% LTV</strong></div><div><span>Liquidation threshold</span><strong>60% LTV</strong></div></div><a class="protocol-reader-link" href="/app/#risk">Open the collateral stress test <span>↗</span></a>`},
  risk:{label:'Risk',eyebrow:'LIMITS & EXPOSURE',title:'Simple access. Explicit conditions.',intro:'A unified market still carries inventory, oracle, credit, and operational risk.',body:`<dl class="protocol-definitions"><div><dt>Market & inventory</dt><dd>Oracle moves and pool cash determine swap output and withdrawal capacity.</dd></div><div><dt>Liquidity & withdrawal</dt><dd>Loans receivable sit in NAV but cannot pay a swap or a withdrawal.</dd></div><div><dt>Collateral & liquidation</dt><dd>A 50% LTV leaves a 10-point buffer to the 60% liquidation threshold. Interest and price both consume that buffer.</dd></div><div><dt>Oracle freshness</dt><dd>Prices older than 30 seconds reject risk-increasing actions.</dd></div><div><dt>Keys</dt><dd>Upgrade, oracle, faucet, and keeper authorities are distinct operator keypairs. None are shipped in the frontend.</dd></div></dl><a class="protocol-reader-link" href="/app/#risk">Explore the risk monitor <span>↗</span></a>`}
};
let pauseJourney=()=>{};
const dialog=document.querySelector('#protocol-dialog'),reader=document.querySelector('#protocol-reader');
function openTopic(key,focusTab=false){const t=topics[key]||topics.overview;pauseJourney();reader.innerHTML=`<div class="protocol-reader-head"><span>RILLVANE / PROTOCOL NOTES</span><button class="protocol-close" data-close-protocol aria-label="Close protocol notes">×</button></div><nav class="protocol-topic-nav" aria-label="Protocol topics">${Object.entries(topics).map(([id,v])=>`<button data-protocol="${id}" ${id===key?'aria-current="page"':''}>${v.label}</button>`).join('')}</nav><article class="protocol-reader-article"><span class="protocol-index">${t.eyebrow}</span><h2 id="protocol-dialog-title">${t.title}</h2><p class="protocol-reader-intro">${t.intro}</p>${t.body}</article><div class="protocol-reader-footer"><span>RLVN / USDC market</span><a href="/app/">Open app ↗</a></div>`;if(!dialog.open)dialog.showModal();reader.scrollTop=0;if(focusTab)reader.querySelector('[aria-current]')?.focus({preventScroll:true});}
export function setupProtocolNotes(pause){pauseJourney=pause;document.addEventListener('click',e=>{const button=e.target.closest('[data-protocol]');if(button){openTopic(button.dataset.protocol,dialog.open);return;}if(e.target.closest('[data-close-protocol]'))dialog.close();});}
const noteGroups=[['.pool-notes',4.35,4.7,5.7,6.25],['.flow-notes',8.4,8.5,8.75,8.93],['.risk-notes',14.6,14.9,15.7,16.05]].map(([s,...range])=>[document.querySelector(s),...range]);
const poolTitle=document.querySelector('.pool-title-wrap');
export function updateProtocolNotes(unit){const fit=(v,a,b)=>Math.max(0,Math.min(1,(v-a)/(b-a)));if(poolTitle)poolTitle.style.opacity=innerWidth>=768?1-fit(unit,4.05,4.3):1;noteGroups.forEach(([el,a,b,c,d])=>{if(!el)return;const amount=fit(unit,a,b)*(1-fit(unit,c,d));el.style.opacity=amount;el.style.visibility=amount>.001?'visible':'hidden';el.style.transform=`translateY(${(1-amount)*18}px)`;el.inert=amount<.1;});}
